import {reviewStatus,deviceProfiles} from './review-state.js';
import {brand,landing,header,footer,comparison,legal,priceCards,mock} from './marketing.js';
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>s.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
const state={user:null,projects:[],project:null,review:null,device:'desktop',width:1440,height:900,capture:false,selected:null,filter:'open',search:'',page:'/',bridge:false,nonce:crypto.randomUUID(),reviewToken:null,recording:null,files:[],screenshot:null};
let poll,toastTimer,mediaURLs=[];
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4000);}
async function api(path,options={}){const headers={...options.headers};if(!(options.body instanceof FormData))headers['Content-Type']='application/json';if(state.reviewToken)headers['X-Review-Session']=state.reviewToken;const res=await fetch(path,{...options,headers,body:options.body&&!(options.body instanceof FormData)?JSON.stringify(options.body):options.body});let data;try{data=await res.json();}catch{throw new Error('The server returned an unexpected response.');}if(!res.ok)throw new Error(data.error||'The request failed.');return data;}
const send=(path,body={},method='POST')=>api(path,{method,body:path==='/api/projects'?{...body,workspaceId:state.workspace?.id}:body});
const formData=form=>Object.fromEntries(new FormData(form));
const badge=s=>`<span class="status ${s.toLowerCase().replaceAll(' ','-')}">● ${esc(s)}</span>`;
const date=s=>new Date(s).toLocaleDateString('en-IN',{day:'numeric',month:'short'});
const field=(label,name,value='',type='text',required=false)=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
function setTitle(title){document.title=title+' · Redlyn';}
function modal(title,content,submit,wide=false,options={}){const previous=document.querySelector('dialog');previous?.close();previous?.remove();const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="ghost small" data-action="close-dialog" aria-label="Close dialog">✕</button></div>${submit?'<form id="dialog-form">':''}<div class="dialog-error"></div>${content}${submit?'<div class="dialog-actions"><button type="button" data-action="close-dialog">Cancel</button><button class="primary" type="submit">'+submit.label+'</button></div></form>':''}`;if(wide)d.style.width='680px';document.body.append(d);if(options.anchored){d.className='pin-composer';d.show();}else d.showModal();d.addEventListener('close',()=>{stopRecording(true);d.remove();});if(submit)d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter||e.target.querySelector('[type=submit]');btn.disabled=true;try{await submit.run(formData(e.target),e.target,d);}catch(err){d.querySelector('.dialog-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;}finally{if(btn.isConnected)btn.disabled=false;}});d.addEventListener('click',e=>{if(e.target===d&&e.offsetX<0)d.close();});return d;}
async function route(){document.querySelector('dialog.pin-composer')?.close();clearInterval(poll);state.reviewToken=null;mediaURLs.forEach(URL.revokeObjectURL);mediaURLs=[];const path=location.pathname;app.innerHTML='<div class="loading">Loading your workspace…</div>';try{if(path==='/'||path==='/pricing'||path==='/features'){app.innerHTML=landing();setTitle('Visual website feedback for agencies');if(path!=='/')setTimeout(()=>document.querySelector('#'+path.slice(1))?.scrollIntoView(),50);return;}if(path==='/compare'){app.innerHTML=comparison();setTitle('Compare website feedback tools');return;}if(['/privacy','/terms','/refund'].includes(path)){app.innerHTML=legal(path.slice(1));setTitle(path.slice(1));return;}if(['/login','/signup'].includes(path)){authPage(path==='/signup');return;}if(['/forgot-password','/reset-password','/verify-email'].includes(path)){accountLinkPage(path);return;}if(path.startsWith('/c/')||path.startsWith('/review/')){await clientGate(path.split('/')[2]);return;}const me=await api('/api/me');state.user=me.user;state.services=me.services;if(!state.user){location.href='/login?next='+encodeURIComponent(path);return;}if(path.startsWith('/invite/')){await invitePage(path.split('/')[2]);return;}if(path.startsWith('/t/')){await startReview(path.split('/')[2],true);return;}state.workspaces=(await api('/api/workspaces')).workspaces;state.workspace=state.workspaces.find(w=>w.id===localStorage.getItem('redlyn-workspace'))||state.workspaces.find(w=>w.owner);if(path.startsWith('/workspace-invite/')){await workspaceInvitePage(path.split('/')[2]);return;}state.projects=(await api('/api/projects?workspace='+state.workspace.id)).projects;state.plan=state.workspace.plan;const pm=path.match(/^\/app\/projects\/([^/]+)(?:\/(.*))?$/);if(pm){await projectPage(pm[1],pm[2]||'overview');return;}state.plan=state.workspace.plan;if(path==='/app/setup')await setupPage();else if(path==='/app/settings')await settingsPage();else if(path==='/app/usage')await usagePage(me);else if(path==='/app/notifications')await notificationsPage();else if(path==='/app/team')await teamPage();else await dashboard(path==='/app/archive');}catch(err){app.innerHTML=`${header()}<main class="legal"><h1>Unable to open this page</h1><div class="error">${esc(err.message)}</div><a class="button" href="/app">Back to dashboard</a><button data-action="reload">Try again</button></main>`;}}
function authPage(signup){setTitle(signup?'Create your workspace':'Log in');app.innerHTML=`<div class="auth-layout"><div class="auth-left"><div class="row spread">${brand}<button class="theme ghost" data-action="theme" aria-label="Toggle dark mode">☼</button></div><div class="auth-form"><h1>${signup?'Create your workspace':'Welcome back'}</h1><p>${signup?'Start collecting pinned feedback in minutes.':'Log in to your Redlyn workspace.'}</p><form id="auth-form"><div id="auth-error"></div>${signup?field('Your name','name','','text',true):''}${field('Email address','email','','email',true)}<label class="field"><span>Password</span><input name="password" type="password" ${signup?'minlength="10"':''} maxlength="200" autocomplete="${signup?'new-password':'current-password'}" required>${signup?'<small>At least 10 characters.</small>':''}</label><button class="primary full" type="submit">${signup?'Create workspace':'Log in'} →</button></form>${signup?'':'<p><a href="/forgot-password">Forgot password?</a></p>'}<div class="divider">or</div><button class="full" data-action="google">G &nbsp; ${signup?'Sign up':'Log in'} with Google</button><p class="fine">Google sign-in requires the operator’s OAuth configuration.</p><p class="fine">By continuing, you agree to our <a href="/terms">Terms</a> and <a href="/privacy">Privacy Policy</a>.</p><p>${signup?'Already have an account? <a href="/login">Log in</a>':'New to Redlyn? <a href="/signup">Create an account</a>'}</p></div><div class="auth-footer">© 2026 Redlyn</div></div><div class="auth-right"><div>${mock()}<h2>Get two links</h2><p class="section-intro">One for your team, one for your client.<br>Same page, different permissions.</p></div></div></div>`;document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await send('/api/auth/'+(signup?'signup':'login'),formData(e.target));const next=new URLSearchParams(location.search).get('next');location.href=next&&next.startsWith('/')&&!next.startsWith('//')?next:'/app';}catch(err){document.querySelector('#auth-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;e.submitter.disabled=false;}};}
function shell(content,active='projects',crumb='Workspace'){const u=state.user;return `<div class="workspace"><aside class="sidebar">${brand}<button class="workspace-name" data-action="workspace-menu">${esc(state.workspace?.name||u.name+'’s workspace')} <small>${esc(state.plan||'Free')} Plan</small> ⌄</button><nav aria-label="Workspace">${[['projects','/app','▦','Dashboard'],['archive','/app/archive','▤','Archive'],['team','/app/team','♙','Team'],['usage','/app/usage','◴','Usage & plan'],['settings','/app/settings','⚙','Settings']].map(([k,url,icon,label])=>`<a href="${url}" class="${active===k?'active':''}">${icon} &nbsp; ${label}</a>`).join('')}</nav><div class="side-bottom"><div class="panel side-usage"><div class="row spread"><span>Websites</span><strong>${state.projects.filter(p=>!p.archived).length}</strong></div><a href="/app/usage" class="danger">Upgrade plan →</a></div><div class="user-row"><span class="avatar">${initials(u.name)}</span><div>${esc(u.name)}<small>${esc(u.email)}</small></div></div><button class="ghost small" style="margin-top:12px" data-action="logout">↪ Log out</button></div></aside><div class="workspace-main"><div class="workspace-top"><span>${crumb}</span><div class="row"><a class="button ghost small" href="/app/notifications" aria-label="Notifications">♧</a><button class="theme ghost" data-action="theme" aria-label="Toggle dark mode">☼</button></div></div><main class="content">${content}</main></div></div>`;}
async function dashboard(archived=false){setTitle(archived?'Archive':'Dashboard');state.dashboardArchived=archived;state.projectFilter='all';state.projectLayout=localStorage.getItem('redlyn-project-layout')||'grid';const p=state.projects.filter(x=>!!x.archived===archived),hour=new Date().getHours(),greeting=hour<12?'morning':hour<18?'afternoon':'evening';app.innerHTML=shell(`<div class="dashboard-heading"><h1>${archived?'Archive':`Good ${greeting}, ${esc(state.user.name.split(' ')[0])}`}</h1><p>${archived?'Restore a review to make its client links available again.':`${p.reduce((n,x)=>n+x.open_count,0)} open comments across ${p.length} review${p.length===1?'':'s'}`}</p>${archived?'':`<form class="create-review" id="create-review"><span aria-hidden="true">◎</span><input aria-label="Website link" name="url" placeholder="Paste a website link: live, staging or a Webflow preview" required><kbd>N</kbd><button class="primary" id="create-review-button" disabled>→ Create review</button></form>`}</div><div class="dashboard-columns"><section><div class="review-list-toolbar"><div class="filters" aria-label="Filter reviews">${[['all','All reviews'],['In review','In review'],['Changes requested','Changes requested'],['Approved','Approved']].map(([v,label])=>`<button class="small ${v==='all'?'active':''}" data-action="project-filter" data-filter="${v}">${label} <span class="count">${v==='all'?p.length:p.filter(x=>reviewStatus(x)===v).length}</span></button>`).join('')}</div><div class="row"><input class="search" id="project-search" placeholder="Search" aria-label="Search reviews"><div class="segmented" aria-label="Layout"><button data-action="project-layout" data-layout="grid" aria-label="Grid view" aria-pressed="${state.projectLayout==='grid'}">▦</button><button data-action="project-layout" data-layout="list" aria-label="List view" aria-pressed="${state.projectLayout==='list'}">☷</button></div></div></div><div id="project-cards"></div>${archived?'':`<div class="panel" style="margin-top:30px"><div class="row spread"><div><strong>Try your first review</strong><p class="hint">Explore pins, screenshots and approvals on Nova Coffee.</p></div><button data-action="demo-project" class="small">Create demo →</button></div></div>`}</section><aside class="latest-activity"><h2>Latest activity</h2><div id="dashboard-activity" class="hint">Loading activity…</div></aside></div>`,archived?'archive':'projects');renderProjects();document.querySelector('#project-search').oninput=()=>renderProjects();const form=document.querySelector('#create-review');if(form){form.url.oninput=()=>{try{normaliseWebsiteURL(form.url.value);document.querySelector('#create-review-button').disabled=false;}catch{document.querySelector('#create-review-button').disabled=true;}};form.onsubmit=e=>{e.preventDefault();safeSave(e.submitter,async()=>{const url=normaliseWebsiteURL(form.url.value),r=await send('/api/projects',{name:new URL(url).hostname.replace(/^www\./,''),url,environment:'staging'});location.href='/app/projects/'+r.id+'?clientToken='+r.clientToken;});};}const a=await api('/api/activity?workspace='+state.workspace.id);if(document.querySelector('#dashboard-activity'))document.querySelector('#dashboard-activity').innerHTML=a.activity.length?a.activity.slice(0,12).map(x=>`<a class="activity-item" href="/app/projects/${x.project_id}/activity"><span class="avatar">${initials(x.author)}</span><div><strong>${esc(x.author)}</strong> ${esc(x.text)}<small class="hint"> · ${esc(x.project_name)}${x.internal?' · Internal':''}</small><time>${new Date(x.created_at).toLocaleString('en-IN')}</time></div></a>`).join(''):'<p>No activity yet. Create a review to get started.</p>';}
function normaliseWebsiteURL(value){const u=new URL(/^https?:\/\//i.test(value.trim())?value.trim():'https://'+value.trim());if(!['http:','https:'].includes(u.protocol)||u.username||u.password||!u.hostname.includes('.')&&u.hostname!=='localhost')throw new Error('Enter a valid website link.');return u.href;}
function renderProjects(){const search=document.querySelector('#project-search').value.toLowerCase(),projects=state.projects.filter(p=>!!p.archived===state.dashboardArchived&&(state.projectFilter==='all'||reviewStatus(p)===state.projectFilter)&&(p.name+' '+p.client+' '+p.url).toLowerCase().includes(search));document.querySelector('#project-cards').innerHTML=projects.length?`<div class="project-grid ${state.projectLayout==='list'?'project-list':''}">${projects.map((p,i)=>`<article class="project-card"><a href="/t/${p.id}" class="project-cover ${['','blue','pink'][i%3]}">${p.cover_id?`<img src="/api/media/${p.cover_id}" alt="Preview of ${esc(p.name)}" loading="lazy">`:`<span>${esc(new URL(p.url).hostname)}</span>`}<span class="env">${reviewStatus(p)}</span></a><div class="project-info"><div class="row spread"><a href="/t/${p.id}"><h3>${esc(p.name)}</h3></a><a class="button ghost small" href="/app/projects/${p.id}" aria-label="Manage ${esc(p.name)}">⋯</a></div><p>${esc(new URL(p.url).hostname)}</p><div class="project-meta"><span><span class="notification-dot"></span> ${p.open_count} open</span><span>${p.feedback_count} comments</span><span>${date(p.created_at)}</span></div>${p.archived?`<button class="small" data-action="restore-project" data-id="${p.id}">Restore review</button>`:''}</div></article>`).join('')}</div>`:`<div class="empty"><div style="font-size:35px">⌖</div><h3>${search?'No matching reviews':state.dashboardArchived?'No archived reviews':state.projectFilter!=='all'?'No '+state.projectFilter.toLowerCase()+' reviews':'Ready for your first review?'}</h3><p>${search?'Try another search.':state.dashboardArchived?'Archived reviews will appear here.':'Paste a website link to get started.'}</p></div>`;}
function testingTeamNotice(testing){return testing?`<div class="panel"><strong>Testing access enabled</strong><p>You can have up to ${testing.members} team members, including yourself, until ${new Date(testing.expires).toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'})}. Use invitation links to add your test accounts.</p></div>`:'';}
async function teamPage(){setTitle('Team');let r;try{r=await api('/api/workspaces/'+state.workspace.id+'/members');}catch{app.innerHTML=shell('<h1>Team</h1><p>You have access to individual reviews in this workspace. Manage their teammates from each review’s Team tab.</p>','team');return;}const manage=['owner','admin'].includes(r.role);app.innerHTML=shell(`<div class="page-heading"><div><h1>Team</h1><p>Teammates can access every review in ${esc(state.workspace.name)}.</p></div>${manage?'<button class="primary" data-action="workspace-invite">＋ Invite member</button>':''}</div>${testingTeamNotice(r.testing)}<div class="panel"><div class="table-scroll"><table><thead><tr><th>Member</th><th>Email</th><th>Role</th><th></th></tr></thead><tbody>${r.members.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.email)}</td><td>${manage&&m.role!=='owner'?`<select class="workspace-role" data-id="${m.id}" aria-label="Role for ${esc(m.name)}">${['developer','designer','admin'].map(v=>`<option value="${v}" ${v===m.role?'selected':''}>${v==='developer'?'Member':v==='admin'?'Admin':'Designer'}</option>`).join('')}</select>`:esc(m.role)}</td><td>${manage&&m.role!=='owner'?`<button class="small danger" data-action="workspace-remove" data-id="${m.id}">Remove</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>${r.invitations.length?`<div class="panel"><h2>Pending invitations</h2>${r.invitations.map(i=>`<div class="row spread activity-item"><span>${esc(i.email)} · ${esc(i.role)}</span><button class="small" data-action="workspace-revoke" data-id="${i.id}">Revoke</button></div>`).join('')}</div>`:''}`,'team');document.querySelectorAll('.workspace-role').forEach(select=>select.onchange=()=>safeSave(select,async()=>{await send('/api/workspaces/'+state.workspace.id+'/members/'+select.dataset.id,{role:select.value},'PATCH');toast('Role updated');}));}
async function workspaceInvitePage(token){const i=await api('/api/workspace-invite/'+token);app.innerHTML=shell(`<div class="panel"><h1>Join ${esc(i.name)}</h1><p>Invited as ${esc(i.role)}${i.email?' using '+esc(i.email):''}.</p><button id="accept-workspace" class="primary">Accept invitation</button></div>`);document.querySelector('#accept-workspace').onclick=e=>safeSave(e.target,async()=>{const r=await send('/api/workspace-invite/'+token);localStorage.setItem('redlyn-workspace',r.workspaceId);location.href='/app';});}
function projectFields(p={}){return `${field('Project name','name',p.name||'','text',true)}${field('Website URL','url',p.url||'','url',true)}${field('Client name','client',p.client||'')}<label class="field"><span>Environment</span><select name="environment">${['staging','production','development'].map(x=>`<option ${p.environment===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Description</span><textarea name="description">${esc(p.description||'')}</textarea></label>`;}
function newProject(){modal('Create a project',projectFields()+`<p class="hint">You’ll get a team link and a separate client link. Some websites block embedded previews.</p>`,{label:'Create project',run:async(b,form,d)=>{const r=await send('/api/projects',b);d.close();location.href='/app/projects/'+r.id+'?clientToken='+r.clientToken;}});}
async function projectPage(id,tab){const r=await api('/api/projects/'+id);state.project=r;const p=r.project;setTitle(p.name);const visibleTabs=[['overview','Overview'],['feedback','Feedback'],['links','Review links'],['members','Team'],['activity','Activity'],['settings','Settings']];const heading=`<div class="page-heading"><div><div class="eyebrow">${esc(p.client||p.environment)}</div><h1>${esc(p.name)}</h1><p>${esc(p.url)}</p></div><a class="button primary" href="/t/${p.id}">Open review ↗</a></div><div class="tabs">${visibleTabs.map(([t,n])=>`<a href="/app/projects/${id}/${t==='overview'?'':t}" class="${tab===t?'active':''}">${n}</a>`).join('')}</div>`;let content='';if(tab==='overview'){const f=r.feedback;content=`<div class="stats">${[['Open',f.filter(x=>['Open','Reopened'].includes(x.status)).length],['In progress',f.filter(x=>x.status==='In progress').length],['In review',f.filter(x=>x.status==='In review').length],['Resolved',f.filter(x=>['Resolved','Approved'].includes(x.status)).length]].map(([n,v])=>`<div class="stat"><span>${n}</span><strong>${v}</strong></div>`).join('')}</div><div class="panel"><div class="row spread"><h2>Recent feedback</h2><a class="button small" href="/app/projects/${id}/feedback">View all</a></div>${feedbackTable(f.slice(0,5),id)}</div><div class="panel"><h2>Page approvals</h2>${r.approvals.length?r.approvals.map(a=>`<div class="row spread"><span class="success">✓ ${esc(a.page)}</span><span class="hint">${esc(a.author)} · ${date(a.created_at)}</span></div>`).join(''):'<p class="hint">No pages approved yet. Resolve feedback and ask your client for sign-off.</p>'}</div>`;}else if(tab==='feedback'){content=`<div class="toolbar"><input class="search" id="feedback-search" placeholder="Search feedback…" aria-label="Search feedback"><select class="search" id="feedback-status" style="width:160px"><option>All statuses</option>${['Open','In progress','In review','Resolved','Reopened'].map(s=>`<option>${s}</option>`).join('')}</select><button class="small" data-action="export">↓ Export CSV</button></div><div class="panel" id="feedback-table">${feedbackTable(r.feedback,id)}</div>`;}else if(tab==='links'){content=await linksPanel(id);}else if(tab==='members'){content=`<div class="panel"><div class="row spread"><h2>Project team</h2><button class="small primary" data-action="invite">＋ Invite member</button></div><p class="hint">Create an invitation link and share it with your teammate.</p><div class="table-scroll"><table><thead><tr><th>Member</th><th>Email</th><th>Role</th><th></th></tr></thead><tbody>${r.members.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${u.role!=='owner'?`<button class="ghost small danger" data-action="remove-member" data-id="${u.id}">Remove</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`;}else if(tab==='activity'){const a=(await api('/api/projects/'+id+'/activity')).activity;content=activityPanel(a);}else if(tab==='settings'){content=`<div class="panel"><h2>Project details</h2><form id="project-settings">${projectFields(p)}<button class="primary">Save changes</button></form></div><div class="panel"><h2>${p.archived?'Restore project':'Archive project'}</h2><p class="hint">Archived projects stay in your workspace. Client links are unavailable while archived.</p><button class="danger" data-action="archive">${p.archived?'Restore project':'Archive project'}</button></div><div class="panel"><h2>Enhanced website review</h2><p class="hint">On websites you control, the optional bridge enables element anchoring, scroll tracking, screenshots and tab restoration. Basic iframe reviews work without it.</p><div class="copy-box"><code>${esc('<script src="'+location.origin+'/bridge.js" data-review-origin="'+location.origin+'"></script>')}</code><button class="small" data-action="copy-bridge">Copy</button></div></div>`;}app.innerHTML=shell(heading+content,'projects',`<a href="/app">Projects</a> / ${esc(p.name)}`);if(tab==='settings')document.querySelector('#project-settings').onsubmit=async e=>{e.preventDefault();await safeSave(e.submitter,async()=>{await send('/api/projects/'+id,formData(e.target),'PATCH');toast('Project updated');});};if(tab==='feedback'){const update=()=>{const search=document.querySelector('#feedback-search').value.toLowerCase(),status=document.querySelector('#feedback-status').value;document.querySelector('#feedback-table').innerHTML=feedbackTable(r.feedback.filter(f=>(f.text+' '+f.author).toLowerCase().includes(search)&&(status==='All statuses'||f.status===status)),id);};document.querySelector('#feedback-search').oninput=update;document.querySelector('#feedback-status').onchange=update;}const clientToken=new URLSearchParams(location.search).get('clientToken');if(clientToken){history.replaceState({},'',location.pathname);shareCreated(clientToken);} }
function feedbackTable(f,id){return f.length?`<div class="table-scroll"><table><thead><tr><th>Feedback</th><th>Status</th><th>Device</th><th>Assignee</th><th>Created</th></tr></thead><tbody>${f.map(x=>`<tr><td><a href="/t/${id}?feedback=${x.id}"><span class="pin-label ${x.internal?'purple':''}">${x.number}</span>${esc(x.text.slice(0,80))}${x.internal?' <span class="hint">♙ Internal</span>':''}</a></td><td>${badge(x.status)}</td><td>${esc(x.device)}</td><td>${esc(x.assignee||'Unassigned')}</td><td>${date(x.created_at)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>No feedback yet</h3><p>Open the review and click a spot to add your first pin.</p></div>';}
async function linksPanel(id){const l=(await api('/api/projects/'+id+'/links')).links;return `<div class="panel"><h2>Team review link</h2><p class="hint">Only authenticated project members can access team feedback and private notes.</p><div class="copy-box"><code>${location.origin}/t/${id}</code><button class="small" data-action="copy" data-value="${location.origin}/t/${id}">Copy</button></div></div><div class="panel"><div class="row spread"><h2>Client review links</h2><button class="primary small" data-action="new-link">＋ Create link</button></div><p class="hint">New link URLs are shown once. Create a replacement if you no longer have the original.</p>${l.map(x=>`<div class="activity-item"><div style="flex:1"><strong>${esc(x.label)}</strong><p class="hint" style="margin:4px 0">${x.revoked?'Revoked':x.expires&&x.expires<Date.now()?'Expired':'Active'} · ${x.expires?'Expires '+date(x.expires):'No expiry'} ${x.protected?'· Password protected':''} ${x.require_email?'· Email required':''} · ${x.can_comment?'Can comment':'View only'} · ${x.can_approve?'Can approve':'No approval'}</p></div>${!x.revoked?`<button class="small danger" data-action="revoke-link" data-id="${x.id}">Revoke</button>`:''}</div>`).join('')}</div>`;}
function shareCreated(token){modal('Share this client review',`<p class="hint">Clients enter their name and leave feedback. Internal notes stay private.</p><div class="copy-box"><code>${location.origin}/c/${token}</code><button class="small" data-action="copy" data-value="${location.origin}/c/${token}">Copy</button></div><p class="hint">Save this link now. For security, it cannot be retrieved later.</p><a href="/c/${token}" class="button full" target="_blank" rel="noopener">Open client review ↗</a>`);}
function activityPanel(a){return `<div class="panel"><h2>Activity timeline</h2>${a.length?a.map(x=>`<div class="activity-item"><span class="avatar">${initials(x.author)}</span><div><strong>${esc(x.author)}</strong> ${esc(x.text)} ${x.internal?'<span class="badge">Internal</span>':''}<time>${new Date(x.created_at).toLocaleString('en-IN')}</time></div></div>`).join(''):'<p class="hint">Activity will appear as your team reviews the website.</p>'}</div>`;}
async function notificationsPage(){setTitle('Notifications');const items=(await api('/api/notifications?workspace='+state.workspace.id)).notifications;app.innerHTML=shell(`<div class="page-heading"><div><h1>Notifications</h1><p>Mentions and assignments addressed to you.</p></div></div><div class="panel">${items.length?items.map(n=>`<div class="activity-item"><span class="avatar">${initials(n.author)}</span><div><a href="/t/${n.project_id}?feedback=${n.feedback_id}" data-action="read-notification" data-id="${n.id}"><strong>${esc(n.author)}</strong> · ${esc(n.project_name)} ${n.read?'':'<span class="notification-dot"></span>'}</a><p>${esc(n.text)} ${n.internal?'<span class="badge">Internal</span>':''}</p><time>${new Date(n.created_at).toLocaleString('en-IN')}</time></div></div>`).join(''):'<p class="hint">No notifications yet. Teammates can mention you using @'+esc(state.user.name)+'.</p>'}</div>`,'notifications');}
async function settingsPage(){setTitle('Settings');app.innerHTML=shell(`<div class="page-heading"><div><h1>Settings</h1><p>Manage your account and workspace preferences.</p></div></div><div class="panel"><h2>Your profile</h2><form id="profile-form">${field('Display name','name',state.user.name,'text',true)}${field('Email','email',state.user.email,'email')}<p class="hint">Your sign-in email cannot be changed here.</p><button class="primary">Save profile</button></form></div><div class="panel"><h2>Workspace</h2><form id="workspace-settings">${field('Workspace name','workspace_name',state.workspace.name,'text',true)}<button class="primary">Save workspace</button></form></div><div class="panel"><h2>Email verification</h2><p>${state.user.emailVerified?'✓ Your email is verified.':'Verify your email to receive mention notifications.'}</p>${state.user.emailVerified?'':'<button data-action="verify-email">Send verification email</button>'}</div><div class="panel"><h2>Connected services</h2><p class="hint">Google sign-in, email and payments.</p><a class="button" href="/app/setup">View service setup</a></div><div class="panel"><h2>Appearance</h2><p class="hint">Choose the theme that works best for you.</p><button data-action="theme">Toggle light / dark mode</button></div><div class="panel"><h2>Account session</h2><button data-action="logout" class="danger">Log out</button></div>`,'settings');document.querySelector('#workspace-settings').onsubmit=e=>{e.preventDefault();safeSave(e.submitter,async()=>{await send('/api/workspaces/'+state.workspace.id,{name:e.target.workspace_name.value},'PATCH');await route();toast('Workspace updated');});};document.querySelector('[name=email]').readOnly=true;document.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();await safeSave(e.submitter,async()=>{const r=await send('/api/me',{name:e.target.name.value},'PATCH');state.user=r.user;toast('Profile updated');});};}
async function usagePage(me){setTitle('Usage & plan');let syncMessage='';if(state.workspace.owner&&me.billingEnabled){try{await send('/api/billing/sync',{workspaceId:state.workspace.id});}catch(e){syncMessage=e.message;}}const u=await api('/api/usage?workspace='+state.workspace.id);state.plan=u.plan;app.innerHTML=shell(`<div class="page-heading"><div><h1>Usage & plan</h1><p>What your workspace includes and how much you've used.</p></div></div>${testingTeamNotice(u.testing)}${syncMessage?`<div class="error">${esc(syncMessage)}</div>`:''}<div class="panel"><h2>${esc(u.plan)} plan</h2><div class="stats">${[['Active websites',u.websites,u.limits.websites],['Team members',u.members,u.limits.members],['Daily preview loads',u.viewsToday,u.limits.views]].map(([label,value,limit])=>`<div class="stat"><span>${label}</span><strong>${value} / ${limit??'Unlimited'}</strong></div>`).join('')}</div>${u.subscription&&u.plan!=='Free'?`<p class="hint">${u.subscription.cancel_at_end?'Cancellation scheduled. Access continues until':'Next billing date:'} ${date(u.subscription.valid_until)}.</p>${state.workspace.owner&&!u.subscription.cancel_at_end?'<button class="danger" data-action="cancel-subscription">Cancel renewal</button>':''}`:''}</div><div class="panel"><h2>Activity</h2><div class="stats">${[['Comments today',u.commentsToday],['Comments this month',u.commentsMonth],['Page views today',u.viewsToday],['Page views this month',u.viewsMonth]].map(([label,value])=>`<div class="stat"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><p class="hint">Activity periods use UTC. Page views count successful isolated preview loads.</p></div>${!me.billingEnabled?'<div class="panel"><h2>Connect billing to upgrade</h2><a class="button" href="/app/setup">View setup steps</a></div>':''}${priceCards(true,u.plan,me.billingEnabled&&state.workspace.owner)}`,'usage');}
function accountLinkPage(path){const reset=path==='/reset-password',verify=path==='/verify-email',token=location.hash.slice(1);if(token)history.replaceState({},'',location.pathname);setTitle(verify?'Verify email':reset?'Reset password':'Forgot password');app.innerHTML=`${header()}<main class="legal"><h1>${verify?'Verify your email':reset?'Choose a new password':'Reset your password'}</h1><form id="account-link-form"><div id="account-link-result"></div>${verify?'':reset?'<label class="field"><span>New password</span><input type="password" name="password" minlength="10" maxlength="200" autocomplete="new-password" required></label>':field('Email address','email','','email',true)}<button class="primary">${verify?'Verify email':reset?'Save password':'Send reset link'}</button></form><p><a href="/login">Back to login</a></p></main>`;document.querySelector('#account-link-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter||e.target.querySelector('button');btn.disabled=true;try{const r=await send('/api/auth/'+(verify?'verify-email':reset?'reset-password':'forgot-password'),{...formData(e.target),token});document.querySelector('#account-link-result').innerHTML=`<p class="success">${esc(r.message||(verify?'Email verified.': 'Password updated. Log in with your new password.'))}</p>`;e.target.querySelectorAll('input').forEach(i=>i.disabled=true);}catch(err){document.querySelector('#account-link-result').innerHTML=`<p class="error">${esc(err.message)}</p>`;btn.disabled=false;}};}
async function setupPage(){setTitle('Service setup');const services=state.services||{};app.innerHTML=shell(`<div class="page-heading"><div><h1>Service setup</h1><p>Connect accounts owned by you to activate these features.</p></div></div><div class="panel"><h2>Google sign-in · ${services.google?'Connected':'Needs setup'}</h2><p>Create a Web application OAuth client in Google Cloud. Register this callback:</p><div class="copy-box"><code>${location.origin}/api/auth/google/callback</code><button data-action="copy" data-value="${location.origin}/api/auth/google/callback">Copy</button></div><p class="hint">The owner configures the client ID, client secret and redirect URI in server settings.</p><a class="button" target="_blank" rel="noopener" href="https://console.cloud.google.com/auth/clients">Open Google Cloud</a></div><div class="panel"><h2>Email delivery · ${services.email?'Connected':'Needs setup'}</h2><p>Create a Resend account and verify a domain you own. Configure its API key and verified sender in server settings.</p><p class="hint">Email activates invitations, password recovery, verification and mention alerts.</p><a class="button" target="_blank" rel="noopener" href="https://resend.com/domains">Open Resend</a></div><div class="panel"><h2>Payments · ${services.billing?'Connected':'Needs setup'}</h2><p>Create a Dodo Payments account and three monthly subscription products: Starter, Agency and Studio. Test checkout before using live payments.</p><p class="hint">Only the workspace owner can manage subscriptions. Usage & plan verifies payment status with Dodo when opened.</p><a class="button" target="_blank" rel="noopener" href="https://app.dodopayments.com">Open Dodo Payments</a></div><div class="panel"><h2>Private Site access</h2><p>The Site is private. Teammates and clients must also be allowed through Site sharing before their application links can open.</p></div>`,'settings');}
async function invitePage(token){const i=await api('/api/invite/'+token);app.innerHTML=shell(`<div class="panel"><h1>You’re invited to ${esc(i.name)}</h1><p>Join as ${esc(i.role)} using ${esc(i.email)}.</p><button class="primary" id="accept-invite">Accept invitation</button></div>`);document.querySelector('#accept-invite').onclick=()=>safeSave(document.querySelector('#accept-invite'),async()=>{const p=await send('/api/invite/'+token);location.href='/app/projects/'+p.id;});}
async function safeSave(button,fn){if(button)button.disabled=true;try{await fn();}catch(e){toast(e.message);}finally{if(button)button.disabled=false;}}
async function clientGate(token){const r=await api('/api/review/'+token);setTitle('Review '+r.project.name);const key='redlyn-review-'+token,stored=sessionStorage.getItem(key);if(stored){state.reviewToken=stored;try{await startReview(r.project.id,false);return;}catch{sessionStorage.removeItem(key);state.reviewToken=null;}}app.innerHTML=`<div class="auth-layout"><div class="auth-left">${brand}<div class="auth-form"><div class="eyebrow">Client review</div><h1>${esc(r.project.name)}</h1><p>Leave feedback right where it belongs. No account needed.</p><form id="client-form"><div id="client-error"></div>${field('Your name','name','','text',true)}${r.emailRequired?field('Email address','email','','email',true):''}${r.passwordRequired?field('Link password','password','','password',true):''}<button class="primary full">Open review →</button></form><p class="fine">${r.permissions.comment?'Click anywhere to pin a comment.':'This is a view-only review.'} Your name will appear beside your feedback.</p></div>${r.branding===false?'':'<p class="fine">Powered by Redlyn</p>'}</div><div class="auth-right"><div>${mock()}<h2>Your feedback. In the right place.</h2></div></div></div>`;document.querySelector('#client-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const session=await send('/api/review/'+token,formData(e.target));state.reviewToken=session.token;sessionStorage.setItem(key,session.token);await startReview(session.projectId,false);}catch(err){document.querySelector('#client-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;e.submitter.disabled=false;}};}
async function startReview(id,team){state.review=await api('/api/projects/'+id);state.project=state.review;state.bridge=false;state.capture=!!state.review.permissions.comment;const initialURL=new URL(state.review.project.url);state.page=initialURL.pathname+initialURL.search;state.previewToken=null;state.directPreview=initialURL.origin===location.origin; if(!state.directPreview&&initialURL.protocol==='https:'){const ticket=await send('/api/projects/'+id+'/preview');state.previewToken=ticket.token;}state.selected=new URLSearchParams(location.search).get('feedback');if(state.selected){const f=state.review.feedback.find(f=>f.id===state.selected);if(f){state.fit=false;state.device=f.device;state.width=f.metadata.viewportWidth||1440;state.height=f.metadata.viewportHeight||900;state.page=f.page;}}setTitle('Review '+state.review.project.name);renderReview();clearInterval(poll);poll=setInterval(async()=>{try{const data=await api('/api/projects/'+id);const changed=JSON.stringify(data.feedback)!==JSON.stringify(state.review.feedback)||JSON.stringify(data.approvals)!==JSON.stringify(state.review.approvals);state.review=data;if(changed&&!document.querySelector('dialog')&&!document.activeElement?.matches('textarea,input,select'))renderFeedback();}catch(e){clearInterval(poll);toast(e.message);}},7000);}
function reviewURL(){const p=state.review.project;try{return new URL(state.page,p.url).href;}catch{return p.url;}}
function frameURL(){return state.previewToken&&!state.directPreview?'/preview/'+state.previewToken+'?url='+encodeURIComponent(reviewURL()):reviewURL();}
function renderReview(){const r=state.review;if(!state.selected&&state.device==='desktop'&&state.fit!==false){state.width=Math.max(320,innerWidth-(innerWidth>760?320:0)-32);state.height=Math.max(400,innerHeight-170);state.fit=true;}app.innerHTML=`<main class="review-layout ${state.sidebarCollapsed?'comments-collapsed':''}"><header class="review-header"><a class="review-back ghost button small" href="/app" aria-label="Back to dashboard" title="Back to dashboard">${reviewIcon('back')}</a>${brand.replace('class="brand"','class="brand" aria-label="Redlyn home" title="Redlyn home"')}<button class="ghost small review-collapse" data-action="collapse-comments" aria-label="Toggle comments sidebar" title="Toggle comments sidebar" aria-expanded="${!state.sidebarCollapsed}">${reviewIcon('sidebar')}</button><div class="review-project"><span class="review-title">${esc(r.project.name)}</span><button class="review-path" data-action="review-page-menu" aria-expanded="false" aria-controls="review-navigation" title="Page navigation">${state.page==='/'?'Home':esc(state.page)} ${reviewIcon('chevron')}</button></div><div class="review-tools"><div class="review-devices"><button class="small device-group" data-action="device-group" data-device="desktop" aria-label="Desktop view" title="Desktop view" aria-pressed="${state.device==='desktop'}">${reviewIcon('desktop')}</button><button class="small device-group" data-action="device-group" data-device="tablet" aria-label="Tablet view" title="Tablet view" aria-pressed="${state.device==='tablet'}">${reviewIcon('tablet')}</button><button class="small device-group" data-action="device-group" data-device="phone" aria-label="Mobile view" title="Mobile view" aria-pressed="${state.device==='phone'}">${reviewIcon('phone')}</button><select id="device-select" aria-label="Device profile"><option value="fit" ${state.fit?'selected':''}>Fit</option>${deviceProfiles.map(([v,t])=>`<option value="${v}" ${v===`${state.device}:${state.width}:${state.height}`?'selected':''}>${t}</option>`).join('')}</select></div><div class="review-modes">${r.permissions.comment?`<button class="small ${state.capture?'active':''}" data-action="capture" id="capture-button" aria-pressed="${state.capture}">${reviewIcon('comment')} Comment</button>`:'<button class="small" id="capture-button" disabled>View only</button>'}<button class="small ${!state.capture?'active':''}" data-action="browse" id="browse-button" aria-pressed="${!state.capture}">${reviewIcon('browse')} Browse</button></div>${r.permissions.approve?`<button class="small approve-control" data-action="approve-page">${reviewIcon('approve')} Approve</button>`:''}${r.team?`<a class="button ghost small review-notifications" href="/app/notifications" aria-label="Notifications" title="Notifications">${reviewIcon('bell')}</a>`:''}<span class="badge mode-label">${r.team?reviewIcon('lock')+' Team view':'Client view'}</span><button class="theme ghost small" data-action="theme" aria-label="Toggle dark mode" title="Toggle theme">${reviewIcon('sun')}</button><button class="ghost small review-shortcuts" data-action="review-more" aria-label="More review controls" title="More review controls">${reviewIcon('more')}</button><button class="small mobile-review-toggle" data-action="toggle-comments">Comments</button>${r.team?`<a class="button small primary review-share" aria-label="Share" title="Share" href="/app/projects/${r.project.id}/links">${reviewIcon('share')} <span>Share</span></a>`:''}</div></header><div class="review-url hide" id="review-navigation"><button class="ghost small" data-action="reload-frame" aria-label="Reload website">↻</button><input id="review-page" value="${esc(reviewURL())}" aria-label="Reviewed page URL"><button class="small" data-action="navigate-frame">Go</button><button class="ghost small" data-action="shortcuts" aria-label="Keyboard shortcuts" title="Keyboard shortcuts">?</button><div class="review-notice" id="review-notice"><span>${state.previewToken?'Connecting preview…':'Direct preview · Connect the bridge for element anchors.'}</span><div class="row"><button class="small" data-action="preview-mode">${state.directPreview?'Isolated preview':'Direct preview'}</button><a href="${esc(reviewURL())}" target="_blank" rel="noopener" class="button small">Open website ↗</a></div></div></div><div class="review-body"><aside class="feedback-sidebar" aria-label="Feedback"><div class="feedback-sidebar-top"><header><strong>Comments <span id="comment-count" class="hint"></span></strong><button class="small ghost mobile-review-toggle" data-action="toggle-comments" aria-label="Close comments">✕</button></header><div class="filters"><button class="small ${state.filter==='open'?'active':''}" data-action="review-filter" data-filter="open">Open</button><button class="small ${state.filter==='resolved'?'active':''}" data-action="review-filter" data-filter="resolved">Resolved</button><button class="small ${state.filter==='all'?'active':''}" data-action="review-filter" data-filter="all">All</button></div><input class="search" id="review-search" placeholder="Search comments…" aria-label="Search comments"></div><div class="feedback-list" id="feedback-list"></div>${r.permissions.comment?'<button class="new-comment-link" data-action="capture">＋ New comment</button>':''}</aside><div class="canvas-area"><div class="canvas-wrap" id="canvas-wrap" style="width:${state.width}px;height:${state.height}px"><iframe id="review-frame" src="${esc(frameURL())}" title="Website under review" sandbox="allow-scripts allow-forms allow-popups ${(state.directPreview||!state.previewToken)&&(new URL(reviewURL()).origin!==location.origin||new URL(reviewURL()).pathname==='/demo.html')?'allow-same-origin':''}" referrerpolicy="no-referrer"></iframe><div class="pin-layer" id="pin-layer" aria-label="Feedback pins"></div></div></div></div><footer class="review-footer"><span id="review-help">${state.capture?'Click anywhere to leave a comment · hold Alt to click through':'Browse the website · choose Comment to leave feedback'}</span><span id="review-device">${state.device} · ${state.width} × ${state.height} &nbsp; <kbd>?</kbd> shortcuts</span></footer></main>`;renderFeedback();document.querySelector('#device-select').onchange=e=>{if(e.target.value==='fit'){actions['fit-preview']();return;}if(e.target.value==='custom'){customDevice();return;}const [d,w,h]=e.target.value.split(':');changeDevice(d,+w,+h);};document.querySelector('#review-search').oninput=e=>{state.search=e.target.value;renderFeedback();};document.querySelector('#review-page').onkeydown=e=>{if(e.key==='Enter')navigateFrame();};document.querySelector('#pin-layer').onclick=e=>{if(!state.capture||e.target!==e.currentTarget)return;if(e.altKey)return;const rect=e.currentTarget.getBoundingClientRect();composePin({x:Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),y:Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height)),viewportOnly:true});};const frame=document.querySelector('#review-frame');frame.onload=()=>{frame.contentWindow.postMessage({type:'redlyn:init',nonce:state.nonce},'*');};setTimeout(()=>{if(frame.isConnected)frame.contentWindow.postMessage({type:'redlyn:init',nonce:state.nonce},'*');},1000);capture(state.capture);document.querySelectorAll('.device-group').forEach(el=>el.classList.toggle('active',el.dataset.device===state.device));requestAnimationFrame(()=>{if(state.fit)resizeReviewFit();});}
function renderFeedback(){const r=state.review;if(!r||!document.querySelector('#feedback-list'))return;const approved=r.approvals.some(a=>a.page===state.page);const approve=document.querySelector('[data-action="approve-page"]');if(approve){approve.disabled=approved;approve.innerHTML=reviewIcon('approve')+(approved?' Approved':' Approve');}const f=r.feedback.filter(f=>f.device===state.device&&f.page===state.page);document.querySelector('#comment-count').textContent=f.filter(f=>!['Resolved','Approved'].includes(f.status)).length+' open';const shown=f.filter(f=>(state.filter==='all'||(state.filter==='resolved'?['Resolved','Approved'].includes(f.status):!['Resolved','Approved'].includes(f.status)))&&(f.text+' '+f.author+' '+f.comments.map(c=>c.text).join(' ')).toLowerCase().includes(state.search.toLowerCase()));document.querySelector('#feedback-list').innerHTML=shown.length?shown.map(f=>feedbackCard(f)).join(''):`<div class="empty" style="padding:28px 10px"><h3>${f.length?'No matching feedback':'No '+state.device+' pins yet'}</h3><p class="hint">${r.permissions.comment?'Click anywhere on the website to leave a comment.':'Feedback will appear here.'}</p></div>`;document.querySelector('#pin-layer').innerHTML=f.map(f=>`<button class="feedback-pin ${f.internal?'internal':''} ${state.selected===f.id?'selected':''} ${['Resolved','Approved'].includes(f.status)?'resolved':''}" style="left:${f.anchor.x*100}%;top:${f.anchor.y*100}%" data-action="select-feedback" data-id="${f.id}" aria-label="Feedback ${f.number}: ${esc(f.text.slice(0,50))}">${f.number}</button>`).join('');if(state.bridge)document.querySelector('#review-frame').contentWindow.postMessage({type:'redlyn:anchors',nonce:state.nonce,anchors:f.map(x=>({id:x.id,anchor:x.anchor}))},'*');loadMedia();document.querySelectorAll('.reply-form').forEach(form=>{form.onsubmit=e=>postReply(e,form.dataset.id);mentionAutocomplete(form.querySelector('textarea'));form.querySelector('textarea').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();form.requestSubmit();}};form.pendingFiles=[];form.querySelector('[type=file]').onchange=e=>{form.querySelector('textarea').required=!(e.target.files.length||form.pendingFiles.length);};form.querySelector('textarea').onpaste=e=>{const files=clipboardImages(e);if(files.length){form.pendingFiles.push(...files);form.querySelector('textarea').required=false;form.querySelector('.reply-files').textContent=form.pendingFiles.length+' images attached';}};});document.querySelectorAll('.feedback-status').forEach(select=>select.onchange=()=>safeSave(select,async()=>{await send('/api/projects/'+r.project.id+'/feedback/'+select.dataset.id,{status:select.value},'PATCH');await refreshReview();}));document.querySelectorAll('.feedback-assignee').forEach(select=>select.onchange=()=>safeSave(select,async()=>{await send('/api/projects/'+r.project.id+'/feedback/'+select.dataset.id,{assignee:select.value},'PATCH');await refreshReview();}));}
function feedbackCard(f){const r=state.review,selected=state.selected===f.id,element=f.anchor.element||{},elementLabel=element.text||element.ariaLabel||element.tag||'Page',width=f.metadata.viewportWidth;return `<article class="feedback-item ${selected?'selected':''}" data-action="select-feedback" data-id="${f.id}"><div class="feedback-author"><span class="pin-label ${f.internal?'purple':''}">${f.number}</span><strong>${esc(f.author)}</strong>${f.internal?'<span class="private">♙ Internal</span>':''}<time>${date(f.created_at)}</time></div><p>${esc(f.text)}</p><div class="feedback-evidence ${selected?'expanded':''}">${attachments(f.attachments.filter(a=>!a.comment_id))}</div><div class="feedback-context"><span class="element-label" title="${esc(elementLabel)}">on “${esc(elementLabel)}”</span><span>${f.device==='phone'?'▯':f.device==='tablet'?'▤':'▣'} ${width?esc(width)+'px':esc(f.device)}</span>${f.assignee?`<span class="comment-assignee"><span class="assignee-dot">${esc(initials(f.assignee))}</span>${esc(f.assignee)}</span>`:''}</div><div class="feedback-bottom">${badge(f.status)}<small>${esc(f.priority)} · ${f.comments.length} replies</small></div>${selected?`<div class="thread">${r.team?`<div class="row spread"><select class="feedback-status" data-id="${f.id}" aria-label="Feedback status">${['Open','In progress','In review','Resolved','Reopened','Approved'].map(s=>`<option ${s===f.status?'selected':''}>${s}</option>`).join('')}</select><select class="feedback-assignee" data-id="${f.id}" aria-label="Assignee"><option value="">Unassigned</option>${r.members.map(u=>`<option value="${esc(u.name)}" ${u.name===f.assignee?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div>`:f.status==='In review'&&(r.permissions.comment||r.permissions.approve)?`<p class="hint">The team says this is fixed. Does it look right?</p><div class="row">${r.permissions.approve?`<button class="small" data-action="looks-good" data-id="${f.id}">✓ Looks good</button>`:''}${r.permissions.comment?`<button class="small" data-action="request-changes" data-id="${f.id}">Request changes</button>`:''}</div>`:f.status==='Resolved'&&r.permissions.comment?`<button class="small" data-action="request-changes" data-id="${f.id}">Reopen feedback</button>`:''}<p class="hint">${esc(f.metadata.viewportWidth||state.width)} × ${esc(f.metadata.viewportHeight||state.height)} · ${esc(f.anchor.element?.tag||'Viewport pin')}${f.anchor.viewportOnly?' · Viewport-relative':''}</p>${f.comments.map(c=>`<div class="reply ${c.internal?'internal':''}"><small><strong>${esc(c.author)}</strong> ${c.internal?'· Internal':''} · ${date(c.created_at)}</small><p>${esc(c.text)}</p>${attachments(f.attachments.filter(a=>a.comment_id===c.id))}</div>`).join('')}${r.permissions.comment?`<form class="reply-form" data-id="${f.id}"><label class="field"><textarea name="text" placeholder="Reply… Use @name to mention" aria-label="Reply" required maxlength="4000"></textarea></label>${r.team?'<label class="check-field" style="font-size:11px"><input type="checkbox" name="internal"> Internal reply</label>':''}<div class="reply-files hint"></div><div class="row spread"><label class="button small ${uploadsAvailable()?'':'hide'}">▧ Attach<input type="file" name="file" accept="image/png,image/jpeg,image/webp,application/pdf" class="hide"></label><button class="small primary">Reply →</button></div></form>`:''}</div>`:''}</article>`;}
function mentionAutocomplete(textarea){const names=[...new Set([...(state.review.members||[]).map(m=>m.name),...state.review.feedback.flatMap(f=>[f.author,...f.comments.filter(c=>!c.internal||state.review.team).map(c=>c.author)])])];let menu=null,index=0,matches=[],start=0;const close=()=>{menu?.remove();menu=null;};const choose=name=>{const end=textarea.selectionStart;textarea.setRangeText('@'+name+' ',start,end,'end');close();textarea.focus();};textarea.addEventListener('input',()=>{close();const before=textarea.value.slice(0,textarea.selectionStart),match=before.match(/(?:^|\s)@([^@\n]*)$/);if(!match)return;start=before.lastIndexOf('@');matches=names.filter(n=>n.toLowerCase().startsWith(match[1].toLowerCase())).slice(0,6);if(!matches.length)return;index=0;menu=document.createElement('div');menu.className='mention-menu';menu.setAttribute('role','listbox');menu.setAttribute('aria-label','Mention a participant');menu.innerHTML=matches.map(n=>`<button type="button" role="option" aria-selected="false">${esc(n)}</button>`).join('');textarea.parentElement.append(menu);[...menu.children].forEach((b,i)=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>choose(matches[i]);});menu.children[0].setAttribute('aria-selected','true');});textarea.addEventListener('keydown',e=>{if(!menu)return;if(['ArrowDown','ArrowUp','Enter','Escape'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(e.key==='Escape')close();else if(e.key==='Enter')choose(matches[index]);else{index=(index+(e.key==='ArrowDown'?1:-1)+matches.length)%matches.length;[...menu.children].forEach((b,i)=>b.setAttribute('aria-selected',String(i===index)));}}},true);textarea.addEventListener('blur',()=>setTimeout(close,150));}
function attachments(list){return list.length?`<div class="attachments">${list.map(a=>a.mime.startsWith('image/')?`<img data-media="${a.id}" alt="${esc(a.name)}" data-action="view-media">`:a.mime.includes('audio')||a.mime==='video/webm'?`<audio controls data-media="${a.id}" aria-label="Voice note"></audio>`:`<button class="small" data-action="download-media" data-id="${a.id}" data-name="${esc(a.name)}">↓ ${esc(a.name)}</button>`).join('')}</div>`:'';}
async function mediaBlob(id){const h=state.reviewToken?{'X-Review-Session':state.reviewToken}:{};const res=await fetch('/api/media/'+id,{headers:h});if(!res.ok)throw new Error('Attachment unavailable.');const src=URL.createObjectURL(await res.blob());mediaURLs.push(src);return src;}
function loadMedia(){document.querySelectorAll('[data-media]').forEach(async el=>{try{el.src=await mediaBlob(el.dataset.media);}catch{el.setAttribute('aria-label','Attachment unavailable');}});}
function clipboardImages(e){if(!uploadsAvailable()){if([...(e.clipboardData?.items||[])].some(i=>i.kind==='file'))toast('Uploads are disabled. Please write your feedback as text.');return [];}const items=[...(e.clipboardData?.items||[])].filter(i=>i.kind==='file'&&i.type.startsWith('image/'));if(!items.length)return [];const files=items.map(i=>i.getAsFile()).filter(Boolean);const allowed=files.filter(f=>['image/png','image/jpeg','image/webp'].includes(f.type)&&f.size>0&&f.size<=10*1024*1024);if(allowed.length!==files.length)toast('Paste PNG, JPEG or WebP images smaller than 10 MB.');if(!e.clipboardData.getData('text/plain'))e.preventDefault();return allowed;}
async function postReply(e,id){e.preventDefault();e.stopPropagation();const form=e.target;await safeSave(e.submitter,async()=>{const b=formData(form),r=await send('/api/projects/'+state.review.project.id+'/feedback/'+id+'/comments',{text:b.text||'Image attachment',internal:!!b.internal});const files=[...(form.pendingFiles||[])];const file=form.querySelector('[type=file]').files[0];if(file)files.push(file);form.pendingFiles=[];for(const file of files)await upload(id,file,r.id);await refreshReview();});}
async function refreshReview(){state.review=await api('/api/projects/'+state.review.project.id);renderFeedback();}
function changeDevice(d,w,h){document.querySelectorAll('.device-group').forEach(el=>{el.classList.toggle('active',el.dataset.device===d);el.setAttribute('aria-pressed',String(el.dataset.device===d));});state.fit=false;state.device=d;state.width=w;state.height=h;state.selected=null;const select=document.querySelector('#device-select');const value=`${d}:${w}:${h}`;select.value=[...select.options].some(o=>o.value===value)?value:'custom';const wrap=document.querySelector('#canvas-wrap');wrap.style.width=w+'px';wrap.style.height=h+'px';document.querySelector('#review-device').textContent=`${d} · ${w} × ${h}`;document.querySelector('#review-frame').contentWindow.postMessage({type:'redlyn:device',nonce:state.nonce,device:d},'*');renderFeedback();}
function customDevice(){modal('Custom viewport',field('Width (px)','width',state.width,'number',true)+field('Height (px)','height',state.height,'number',true),{label:'Apply size',run:async(b,f,d)=>{if(+b.width<280||+b.width>2560||+b.height<400||+b.height>2000)throw new Error('Use a width of 280–2560 and height of 400–2000.');changeDevice(+b.width<600?'phone':+b.width<1100?'tablet':'desktop',+b.width,+b.height);d.close();}});}
function navigateFrame(){document.querySelector('dialog.pin-composer')?.close();try{const u=new URL(document.querySelector('#review-page').value);if(!['http:','https:'].includes(u.protocol)||u.origin!==new URL(state.review.project.url).origin)throw new Error('Use a page on the project’s website.');state.page=u.pathname+u.search;state.bridge=false;document.querySelector('#review-frame').src=frameURL();renderFeedback();}catch(e){toast(e.message||'Enter a valid website URL.');}}
function capture(on=true){if(on&&document.querySelector('dialog.pin-composer[open]'))return;if(!state.review?.permissions.comment)on=false;state.capture=on;const comment=document.querySelector('#capture-button'),browse=document.querySelector('#browse-button'),layer=document.querySelector('#pin-layer');comment?.classList.toggle('active',on);comment?.setAttribute('aria-pressed',String(on));browse?.classList.toggle('active',!on);browse?.setAttribute('aria-pressed',String(!on));layer?.classList.toggle('capturing',on&&!state.bridge);const help=document.querySelector('#review-help');if(help)help.textContent=on?'Click anywhere to leave a comment · hold Alt to click through':state.review?.permissions.comment?'Browse the website · choose Comment to leave feedback':'View-only review · browse the website';document.querySelector('#review-frame')?.contentWindow.postMessage({type:'redlyn:mode',nonce:state.nonce,capture:on},'*');}
function uploadsAvailable(){return state.review?.uploadsEnabled!==false&&state.services?.uploads!==false;}
async function composePin(anchor,screenshot){if(!uploadsAvailable())screenshot=null;if(document.querySelector('dialog.pin-composer'))return;capture(false);state.pendingAnchor=anchor;state.screenshot=screenshot||null;state.files=[];state.voice=null;const r=state.review;const composer=modal('New comment',`<div class="composer"><div class="pin-composer-context"><span title="${esc(anchor.element?.text||anchor.element?.ariaLabel||anchor.element?.tag||'Page')}">${esc(anchor.element?.text||anchor.element?.ariaLabel||anchor.element?.tag||'Page')}</span><span>▣ ${state.width}px</span></div><label class="field"><textarea name="text" id="comment-text" placeholder="Leave your feedback…" aria-label="Comment" maxlength="4000" required></textarea></label><div class="composer-media-tools ${uploadsAvailable()?'':'hide'}"><label class="button small ghost" title="Attach image or file">▧<span>Attach</span><input type="file" id="comment-file" class="hide" accept="image/png,image/jpeg,image/webp,application/pdf" multiple></label><button type="button" class="small ghost" data-action="record" id="record-button">◉ Voice</button><button type="button" class="small hide" data-action="stop-record" id="stop-record-button">■ Stop</button><span id="record-time" class="hint">90s max</span></div><div id="voice-preview"></div>${uploadsAvailable()?'':'<p class="hint">Text feedback is available. Image, screenshot and voice uploads are disabled for this free setup.</p>'}<span class="hint" id="file-names"></span><div class="composer-screenshot-slot ${uploadsAvailable()?'':'hide'}">${screenshot?composerScreenshot(screenshot):'<button type="button" class="small" data-action="screen-capture">▧ Capture screenshot</button>'}</div><div class="composer-options">${r.team?'<label class="composer-visibility"><span>Visibility</span><select name="internal" aria-label="Comment visibility"><option value="">Client</option><option value="internal">Internal</option></select></label>':'<span class="badge">Client feedback</span>'}<label class="composer-priority"><span>Priority</span><select name="priority" aria-label="Priority"><option>Normal</option><option>Low</option><option>High</option><option>Urgent</option></select></label></div></div>`,{label:'Post comment',run:async(b,f,d)=>{if(state.recording)throw new Error('Stop your recording before posting.');const result=await send('/api/projects/'+r.project.id+'/feedback',{text:b.text||(state.voice?'Voice note':state.files.length?'Image attachment':''),internal:!!b.internal,priority:b.priority,anchor:state.pendingAnchor,device:state.device,page:state.page,metadata:{viewportWidth:state.width,viewportHeight:state.height,browser:navigator.userAgent,screenWidth:screen.width,screenHeight:screen.height,dpr:devicePixelRatio}});try{if(state.screenshot){const blob=await(await fetch(state.screenshot)).blob();await upload(result.id,new File([blob],'screenshot.png',{type:'image/png'}));}if(state.voice)await upload(result.id,new File([state.voice],'voice-note.webm',{type:state.voice.type}));for(const file of state.files)await upload(result.id,file);}catch(e){toast('Comment saved; an attachment failed: '+e.message);}state.selected=result.id;d.close();await refreshReview();toast('Feedback posted');}},false,{anchored:true});anchorComposer(composer,anchor);composer.addEventListener('close',()=>{if(document.querySelector('#review-frame')&&state.review?.project.id===r.project.id)capture(true);});const updateFiles=()=>{document.querySelector('#file-names').textContent=state.files.map(f=>f.name).join(', ');document.querySelector('#comment-text').required=!(state.files.length||state.voice);};document.querySelector('#comment-file').onchange=e=>{state.files.push(...e.target.files);e.target.value='';updateFiles();};document.querySelector('#comment-text').onpaste=e=>{const files=clipboardImages(e);if(files.length){state.files.push(...files);updateFiles();}};mentionAutocomplete(document.querySelector('#comment-text'));document.querySelector('#comment-text').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();document.querySelector('#dialog-form').requestSubmit();}};composer.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();composer.close();}});document.querySelector('#comment-text').focus({preventScroll:true});}
async function upload(id,file,commentId){if(!uploadsAvailable())throw new Error('Uploads are disabled for this setup.');const data=new FormData();data.append('file',file);if(commentId)data.append('commentId',commentId);await api('/api/projects/'+state.review.project.id+'/feedback/'+id+'/uploads',{method:'POST',body:data});}
async function record(){if(!uploadsAvailable()){toast('Voice uploads are disabled for this setup.');return;}const composer=document.querySelector('dialog.pin-composer');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!composer?.isConnected||!composer.open){stream.getTracks().forEach(t=>t.stop());return;}const chunks=[];const recorder=new MediaRecorder(stream);state.recording={recorder,stream,start:Date.now(),cancelled:false};const current=state.recording;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());clearInterval(current.timer);if(current.cancelled)return;state.voice=new Blob(chunks,{type:recorder.mimeType});const textarea=document.querySelector('#comment-text');if(textarea)textarea.required=false;const el=document.querySelector('#voice-preview');if(el){const src=URL.createObjectURL(state.voice);mediaURLs.push(src);el.innerHTML=`<audio controls src="${src}" style="width:100%;margin-top:10px"></audio>`;document.querySelector('#record-button').textContent='↻ Record again';document.querySelector('#record-button').classList.remove('hide');document.querySelector('#stop-record-button').classList.add('hide');document.querySelector('#record-time').classList.remove('recording');}};recorder.start();document.querySelector('#record-button').classList.add('hide');document.querySelector('#stop-record-button').classList.remove('hide');document.querySelector('#record-time').classList.add('recording');current.timer=setInterval(()=>{const seconds=Math.floor((Date.now()-current.start)/1000);const el=document.querySelector('#record-time');if(el)el.textContent=`Recording ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;if(seconds>=90)stopRecording();},250);}catch(e){toast('Microphone unavailable. Allow microphone access to record a voice note.');}}
function stopRecording(cancel=false){const current=state.recording;if(!current)return;current.cancelled=cancel;state.recording=null;if(current.recorder.state!=='inactive')current.recorder.stop();clearInterval(current.timer);current.stream.getTracks().forEach(t=>t.stop());}
async function screenCapture(){if(!uploadsAvailable()){toast('Screenshot uploads are disabled for this setup.');return;}try{const stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});const video=document.createElement('video');video.srcObject=stream;await video.play();await new Promise(r=>video.requestVideoFrameCallback?video.requestVideoFrameCallback(r):setTimeout(r,250));const c=document.createElement('canvas');c.width=video.videoWidth;c.height=video.videoHeight;c.getContext('2d').drawImage(video,0,0);stream.getTracks().forEach(t=>t.stop());state.screenshot=c.toDataURL('image/png');const slot=document.querySelector('.composer-screenshot-slot');if(slot)slot.innerHTML=composerScreenshot(state.screenshot);toast('Screenshot attached');}catch{toast('Screenshot cancelled or screen capture is unavailable in this browser.');}}
window.addEventListener('message',e=>{const frame=document.querySelector('#review-frame');if(!frame||e.source!==frame.contentWindow||e.data?.nonce!==state.nonce)return;const msg=e.data;if(msg.type==='redlyn:positions'){for(const p of msg.positions||[]){const el=document.querySelector('.feedback-pin[data-id="'+p.id+'"]');if(el){el.style.left=p.x+'px';el.style.top=p.y+'px';}}}if(msg.type==='redlyn:navigate'){document.querySelector('#review-page').value=msg.url;navigateFrame();}if(msg.type==='redlyn:preview-error'){document.querySelector('#review-notice').firstElementChild.textContent='This page cannot load in the isolated preview. Try Direct preview or Open website.';}if(msg.type==='redlyn:capture-asset'&&state.capture){api('/api/projects/'+state.review.project.id+'/capture-asset?url='+encodeURIComponent(msg.url)).then(r=>frame.contentWindow.postMessage({type:'redlyn:capture-asset-result',nonce:state.nonce,id:msg.id,data:r.data},'*')).catch(()=>frame.contentWindow.postMessage({type:'redlyn:capture-asset-result',nonce:state.nonce,id:msg.id,data:null},'*'));return;}if(msg.type==='redlyn:ready'){if(msg.url){try{const u=new URL(msg.url);if(u.origin===new URL(state.review.project.url).origin){state.page=u.pathname+u.search;document.querySelector('#review-page').value=u.href;}}catch{}}state.bridge=true;document.querySelector('#review-notice').firstElementChild.className='success';document.querySelector('#review-notice').firstElementChild.textContent=`✓ Connected preview · Element anchors, scroll tracking and ${state.previewToken&&!state.directPreview?'rendered':'automatic'} screenshots enabled.`;frame.contentWindow.postMessage({type:'redlyn:mode',nonce:state.nonce,capture:state.capture},'*');document.querySelector('#pin-layer').classList.remove('capturing');renderFeedback();}if(msg.type==='redlyn:pin'&&state.capture&&msg.anchor&&Number.isFinite(msg.anchor.x)&&Number.isFinite(msg.anchor.y)){composePin(msg.anchor,typeof msg.screenshot==='string'&&msg.screenshot.startsWith('data:image/png;base64,')?msg.screenshot:null);}if(msg.type==='redlyn:scroll'&&state.bridge){const layer=document.querySelector('#pin-layer');state.scroll={x:msg.x,y:msg.y,width:msg.width,height:msg.height};for(const pin of layer.querySelectorAll('[data-id]')){const f=state.review.feedback.find(f=>f.id===pin.dataset.id);if(f&&!f.anchor.viewportOnly){pin.style.left=((f.anchor.documentX||f.anchor.x*msg.width)-msg.x)+'px';pin.style.top=((f.anchor.documentY||f.anchor.y*msg.height)-msg.y)+'px';}}}});
function selectFeedback(id){state.selected=state.selected===id?null:id;const f=state.review.feedback.find(x=>x.id===id);if(f&&state.selected){if(f.device!==state.device||f.metadata.viewportWidth&&f.metadata.viewportWidth!==state.width||f.metadata.viewportHeight&&f.metadata.viewportHeight!==state.height)changeDevice(f.device,f.metadata.viewportWidth||1440,f.metadata.viewportHeight||900);state.selected=id;if(f.page!==state.page){state.page=f.page;state.bridge=false;const frame=document.querySelector('#review-frame');frame.src=frameURL();document.querySelector('#review-page').value=reviewURL();}if(state.bridge)document.querySelector('#review-frame').contentWindow.postMessage({type:'redlyn:locate',nonce:state.nonce,anchor:f.anchor},'*');}renderFeedback();}
function shortcuts(){modal('Keyboard shortcuts',`<div class="stack">${[['C','Add a pin'],['J','Next feedback'],['K','Previous feedback'],['R','Resolve selected feedback (team)'],['Esc','Cancel pin or close dialog'],['Enter','Post comment or reply'],['Shift + Enter','New line'],['?','Show keyboard shortcuts']].map(([k,t])=>`<div class="row spread"><span>${t}</span><kbd>${k}</kbd></div>`).join('')}</div>`);}
function exportCSV(){const f=state.project.feedback;const rows=[['Number','Comment','Status','Priority','Device','Author','Assignee','Internal','Page','Created'],...f.map(x=>[x.number,x.text,x.status,x.priority,x.device,x.author,x.assignee,x.internal?'Yes':'No',x.page,x.created_at])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""').replace(/^[=+\-@]/,"'"+String(v)[0])+'"').join(',')).join('\r\n');download(URL.createObjectURL(new Blob([csv],{type:'text/csv'})),state.project.project.name+'-feedback.csv');}
function download(url,name){const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
